#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_get_index_out_of_bounds(void) {
    Vector* vec = NULL;
    int result = 0;

    vec = helper_create_vector(10);
    TEST_ASSERT_NOT_NULL(vec);

    int values[] = {10, 20, 30};
    int fill_result = helper_fill_vector(vec, values, 3);
    TEST_ASSERT_EQUAL_INT(0, fill_result);

    int length = len(vec);
    TEST_ASSERT_EQUAL_INT(3, length);

    result = get(vec, 3);
    TEST_ASSERT_EQUAL_INT(-1, result);

    result = get(vec, 5);
    TEST_ASSERT_EQUAL_INT(-1, result);

    result = get(vec, -1);
    TEST_ASSERT_EQUAL_INT(-1, result);

    helper_cleanup_vector(vec);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_get_index_out_of_bounds);
    return UNITY_END();
}

